import{_ as e,a as l,b as r,c as t,d as s,e as n,f as d,g as c,h as a,i,j as p,k as m,l as u}from"./chunks/ADB8.B4evyQaN.js";import{_ as b,o as h,c as g,a3 as _}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Android Debug Bridge (ADB)","description":"","frontmatter":{"source_hash":"3c220d5612","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/troubleshoot/ADB.md","filePath":"it/troubleshoot/ADB.md"}'),v={name:"it/troubleshoot/ADB.md"};function f(D,o,A,w,B,S){return h(),g("div",null,[...o[0]||(o[0]=[_('<h3 id="prepare-your-device-for-debug" tabindex="-1">Preparare il dispositivo per il debug <a class="header-anchor" href="#prepare-your-device-for-debug" aria-label="Permalink to &quot;Preparare il dispositivo per il debug {#prepare-your-device-for-debug}&quot;">​</a></h3><p>Questo passaggio è obbligatorio per collegarlo tramite ADB con un collegamento fisico. Se il tuo dispositivo non ha un connettore USB fisico devi usare ADB tramite Wi-Fi (documentazione in arrivo).</p><p>Se vuoi fare il debug di uno smartphone, passa direttamente a <a href="#smartphone">questa sezione</a>.</p><h4 id="smartwatch" tabindex="-1">Smartwatch <a class="header-anchor" href="#smartwatch" aria-label="Permalink to &quot;Smartwatch {#smartwatch}&quot;">​</a></h4><ol><li>Attiva le Opzioni sviluppatore<br> Impostazioni -&gt; Info -&gt; Versioni -&gt; Numero build<br> Tocca 7 volte il numero di build finché l&#39;orologio non mostra &quot;sei uno sviluppatore&quot;.<br><img src="'+e+'" style="zoom:75%;"></li><li>Impostazioni -&gt; Opzioni sviluppatore -&gt; Debug ADB<br> Attiva il Debug ADB<br><img src="'+l+'" style="zoom:75%;"></li></ol><h4 id="smartphone" tabindex="-1">Smartphone <a class="header-anchor" href="#smartphone" aria-label="Permalink to &quot;Smartphone {#smartphone}&quot;">​</a></h4><ol><li>Attiva le Opzioni sviluppatore<br> Impostazioni -&gt; Info -&gt; Software -&gt; Numero build<br> Tocca 7 volte il numero di build finché il telefono non mostra &quot;sei uno sviluppatore&quot;.<br><img src="'+r+'" style="zoom:75%;"></li><li>Impostazioni -&gt; Opzioni sviluppatore -&gt; Debug USB<br> Attiva il Debug ADB<br><img src="'+t+'" style="zoom:75%;"></li></ol><h3 id="install-adb-on-a-windows-computer" tabindex="-1">Installare ADB su un computer Windows <a class="header-anchor" href="#install-adb-on-a-windows-computer" aria-label="Permalink to &quot;Installare ADB su un computer Windows {#install-adb-on-a-windows-computer}&quot;">​</a></h3><ol><li><p>Scarica <a href="https://developer.android.com/studio/releases/platform-tools#downloads" target="_blank" rel="noreferrer">Android Debug Bridge</a> sul computer.<br><code>1</code> Apri la cartella Download<br><code>2</code> Apri il file che hai scaricato<br><code>3</code> Seleziona tutti i file<br><code>4</code> Copiali nella cartella <code>5</code> adb che hai creato in C:</p><img src="'+s+'"></li><li><p>Apri una nuova finestra del prompt dei comandi (<code>Start -&gt; Run - &gt; cmd</code>) con privilegi di amministratore.<br><img src="'+n+'"></p></li></ol><h3 id="sideload-an-app-with-adb-in-windows" tabindex="-1">Installare un&#39;app con ADB in Windows <a class="header-anchor" href="#sideload-an-app-with-adb-in-windows" aria-label="Permalink to &quot;Installare un&#39;app con ADB in Windows {#sideload-an-app-with-adb-in-windows}&quot;">​</a></h3><ol><li>Collega il dispositivo (orologio/telefono) al computer con un cavo USB e sblocca lo schermo.</li><li>Digita <code>cd \\adb</code><br><img src="'+d+'"></li><li>Digita <code>adb devices</code><br><img src="'+c+'"></li><li>Guarda il dispositivo collegato e autorizza il debug, sempre.<br><img src="'+a+'" style="zoom:75%;"><br><img src="'+i+'" style="zoom:75%;"></li><li>Digita di nuovo <code>adb devices</code><br> Ora dovresti vedere il tuo dispositivo nell&#39;elenco.<br><img src="'+p+'"></li><li>Copia il file che vuoi installare nella cartella C:\\ADB (chiamiamolo per esempio <code>myapplication.apk</code>; se il nome contiene spazi rinominalo con qualcosa di breve e semplice, come <code>oop.apk</code> o <code>xdrip.apk</code>).</li><li>Digita il comando <code>adb install -r myapplication.apk</code> e attendi il completamento (sostituisci <code>myapplication</code> con il nome della tua app).</li><li>Ora l&#39;app dovrebbe essere presente sul dispositivo.</li></ol><h3 id="install-adb-on-a-mac" tabindex="-1">Installare ADB su un Mac <a class="header-anchor" href="#install-adb-on-a-mac" aria-label="Permalink to &quot;Installare ADB su un Mac {#install-adb-on-a-mac}&quot;">​</a></h3><ol><li>Scarica <a href="https://developer.android.com/studio/releases/platform-tools#downloads" target="_blank" rel="noreferrer">Android Debug Bridge</a> sul computer.<br><code>1</code> Apri la cartella Download nel Finder<br><code>2</code> Fai clic con il tasto destro sulla cartella platform tools<br><code>3</code> Seleziona Nuovo terminale nella cartella</li></ol><img src="'+m+'"><h3 id="sideload-an-app-with-adb-in-ios" tabindex="-1">Installare un&#39;app con ADB in macOS <a class="header-anchor" href="#sideload-an-app-with-adb-in-ios" aria-label="Permalink to &quot;Installare un&#39;app con ADB in macOS {#sideload-an-app-with-adb-in-ios}&quot;">​</a></h3><ol><li><p>Collega il dispositivo (orologio/telefono) al computer con un cavo USB e sblocca lo schermo.</p></li><li><p>Digita <code>./adb devices</code><br><img src="'+u+'"></p></li><li><p>Guarda il dispositivo collegato e autorizza il debug, sempre.<br><img src="'+a+'" style="zoom:75%;"><br><img src="'+i+'" style="zoom:75%;"></p></li><li><p>Digita di nuovo <code>./adb devices</code><br> Ora dovresti vedere il tuo dispositivo nell&#39;elenco.</p></li><li><p>Copia il file che vuoi installare nella cartella platform tools (chiamiamolo per esempio <code>myapplication.apk</code>; se il nome contiene spazi rinominalo con qualcosa di breve e semplice, come <code>oop.apk</code> o <code>xdrip.apk</code>).</p></li><li><p>Digita il comando <code>./adb install -r myapplication.apk</code> e attendi il completamento (sostituisci <code>myapplication</code> con il nome della tua app).</p></li><li><p>Ora l&#39;app dovrebbe essere presente sul dispositivo.</p></li></ol><h3 id="install_failed_version_downgrade" tabindex="-1">INSTALL_FAILED_VERSION_DOWNGRADE <a class="header-anchor" href="#install_failed_version_downgrade" aria-label="Permalink to &quot;INSTALL_FAILED_VERSION_DOWNGRADE {#install_failed_version_downgrade}&quot;">​</a></h3><p>Probabilmente significa che l&#39;app è già presente sul dispositivo in una versione più recente.</p><p>Prova a trovarla e a disinstallarla.</p><p>Se non c&#39;è modo di disinstallarla, prova a installarla con l&#39;opzione di downgrade:</p><p>(Windows) <code>adb install -r -d myapplication.apk</code></p><p>(Mac) <code>./adb install -r -d myapplication.apk</code></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.08.02" target="_blank" rel="noreferrer"><em>Ultima modifica 4/8/2024</em></a></p>',24)])])}const I=b(v,[["render",f]]);export{q as __pageData,I as default};
